h=load_history(); l=load_lab()
def parse(q):
 out=[]
 for s in re.split(r'### Choice ',q)[1:]:
  def get(p):
   m=re.search(p,s); return m.group(1) if m else None
  a={'letter':s[0], 'depth':get(r'- Depth: (\d+)'), 'residual':get(r'- Residual connections: (True|False)'), 'activation':get(r'- Activation: (\w+)'), 'ln':get(r'- Layer norm per layer: (\[[^\n]+\])'),'opt':get(r'- Optimizer: (\w+)'),'lr':get(r'- Learning rate: ([\deE.+-]+)'), 'wd':get(r'- Weight decay: ([\deE.+-]+)'), 'mom':get(r'- Momentum: ([\d.]+)')}
  if a['depth'] and a['ln']:
   a['depth']=int(a['depth']); a['ln']=[x=='True' for x in re.findall(r'True|False',a['ln'])]; a['residual']=a['residual']=='True'
   out.append(a)
 return out
print(parse(h[0]['question']))
for mode in ['sgd','adaptive']:
 pairs=[]
 for r in h:
  if r['family']!='synthetic_tabular_classification' or r['question_id']=='q_710046': continue
  cs=parse(r['question']); gold=re.findall('[A-E]',r['answer'])
  for a in cs:
   for b in cs:
    if a['residual'] or not b['residual'] or a['depth']<4 or b['depth']>2 or not a['ln'][-1] or sum(a['ln'])<=sum(b['ln']): continue
    if a['opt']!=b['opt'] or a['lr']!=b['lr']: continue
    if (a['opt']=='SGD')!=(mode=='sgd'): continue
    if len(gold)==1 and gold[0] not in [a['letter'],b['letter']]: continue
    if len(gold)>1 and not all(z in gold for z in [a['letter'],b['letter']]): continue
    win=gold[0]==a['letter'] if len(gold)==1 else gold.index(a['letter'])<gold.index(b['letter'])
    pairs.append((r['question_id'],win,'smooth_additive' in r['question'],a['activation']==b['activation'],a['letter'],b['letter']))
 print(mode, len(pairs),sum(x[1] for x in pairs),pairs)
"}

